Lemma dec_munmap_ok : forall a len (aw nw : word), aw = Z_to_bv 64 a -> nw = Z_to_bv 64 (mmap_len len) ->
  dec_munmap a len (mkEffectU (Z_to_bv 64 0) [] [] [(aw, nw)] [] []) = Some (RgDone true).
Proof.
